cat > $S/h.cc <<'EOF'
#include <chrono>
#include <cstdio>
#include <cstdint>
#include <random>
#include <vector>
#include <algorithm>
#include "arrow/util/bitmap_ops.h"
int main(int argc, char** argv) {
  std::mt19937_64 rng(42);
  int sizes[] = {16, 1024, 131072};
  std::vector<uint8_t> buf(131072 + 16);
  for (auto& b : buf) b = rng();
  uint64_t chk = 0;
  for (int nbytes : sizes) {
    long iters = 400000000L / (nbytes + 64);
    double best = 1e9;
    for (int r = 0; r < 15; r++) {
      auto t0 = std::chrono::steady_clock::now();
      for (long i = 0; i < iters; i++) {
        int64_t c = arrow::internal::CountSetBits(buf.data(), 0, nbytes * 8);
        asm volatile("" : "+r"(c)); chk += c;
      }
      double dt = std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();
      best = std::min(best, dt / iters);
    }
    printf("%d %.3f\n", nbytes, best * 1e9);
  }
  // correctness checksum over offsets/lengths
  uint64_t cs = 0;
  for (int off = 0; off < 70; off++) for (int len = 0; len < 600; len++)
    cs = cs * 31 + arrow::internal::CountSetBits(buf.data(), off, len);
  printf("checksum %llu %llu\n", (unsigned long long)chk, (unsigned long long)cs);
}
EOF
